import Foundation

// Articles are generated by generator/generate.py on a GitHub Actions schedule and
// published as static JSON on the repo's gh-pages branch.
class GeneratedArticleAPIService: GeneratedArticleRepo {
    private let baseURL: URL

    init(baseURL: URL = GeneratedArticleAPIService.defaultBaseURL) {
        self.baseURL = baseURL
    }

    // ARTICLES_BASE_URL lets a local run point at generator output served from the Mac.
    static var defaultBaseURL: URL {
        if let override = ProcessInfo.processInfo.environment["ARTICLES_BASE_URL"], let url = URL(string: override) {
            return url
        }
        return URL(string: "https://harshsepi0l.github.io/laniakea/articles/")!
    }

    func fetchGeneratedArticle(path: String, completion: @escaping (Result<GeneratedArticle?, Error>) -> Void) {
        guard let url = URL(string: path, relativeTo: baseURL)?.absoluteURL else {
            completion(.failure(URLError(.badURL)))
            return
        }
        URLSession.shared.dataTask(with: url) { data, response, error in
            if let error {
                completion(.failure(error))
                return
            }
            guard let http = response as? HTTPURLResponse else {
                completion(.failure(URLError(.badServerResponse)))
                return
            }
            if http.statusCode == 404 {
                completion(.success(nil))
                return
            }
            guard http.statusCode == 200, let data else {
                completion(.failure(URLError(.badServerResponse)))
                return
            }
            do {
                completion(.success(try JSONDecoder().decode(GeneratedArticle.self, from: data)))
            } catch {
                completion(.failure(error))
            }
        }.resume()
    }
}
